import{_ as s,l as o,o as e,c as i,v as T,p as l,x as t,d as n,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const u=JSON.parse('{"title":"RTT 不公平","description":"","frontmatter":{"title":"RTT 不公平","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/cc-fairness-rtt.md","filePath":"cs/cc-fairness-rtt.md","lastUpdated":1789023840000}'),p={name:"cs/cc-fairness-rtt.md"};function R(h,a,A,_,m,E){const r=o("Mermaid");return e(),i("div",null,[a[1]||(a[1]=T('<h1 id="rtt-不公平" tabindex="-1">RTT 不公平 <a class="header-anchor" href="#rtt-不公平" aria-label="Permalink to &quot;RTT 不公平&quot;">​</a></h1><div class="epigraph"><p>AIMD 每 RTT 加一 MSS，RTT 短的流窗口涨得快，占满同一瓶颈；公平几何假定的同步同 RTT 在真实互联网不成立。</p><footer>—— 据 Floyd and Jacobson 对 RTT 的讨论；Chiu–Jain 模型对照；Kurose and Ross 整理</footer></div><p><a href="/cs/aimd-dynamics">AIMD</a> 在同 RTT 下收敛。<a href="/cs/keepalive-half-open">上一课</a> 不改窗口动力学。缺口是<strong>异质 RTT</strong>：局域网流 vs 卫星流共享核心。本课不把 RED 参数写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>cwnd ← cwnd+1 每 RTT，则速率 ≈ cwnd/RTT，增长 \\(1/\\mathrm{RTT}^2\\) 量级。短 RTT 流抢占。卫星用户即使用对窗口缩放，仍被数据中心旁路流压。CUBIC 用墙钟时间减弱依赖，但不消灭。BBR 后课用带宽估计，仍有 RTT 噪声问题。这不是政策不公，是控制律。</p><p>不要把「不公平」写成必须用 WFQ 才能上网；WFQ 后课是调度器解。</p><p><span class="marginnote">经典 TCP 文献讨论 RTT bias。本课不给数值仿真作业。</span></p><h3 id="每-rtt-加一偏袒短路径" tabindex="-1">每 RTT 加一偏袒短路径 <a class="header-anchor" href="#每-rtt-加一偏袒短路径" aria-label="Permalink to &quot;每 RTT 加一偏袒短路径&quot;">​</a></h3><p>这是控制律，不是商业不公。CUBIC/BBR 缓解不取消。数据中心 RTT 同质，公网否。CDN 减 RTT 也改份额。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：同 RTT 相位图 vs 两 RTT。画：快流占更大份额。AQM 若按队列延迟标，可给长 RTT 一点呼吸，不能完全抹平。ECN 同样按事件，事件频率仍随 RTT。</p>',11)),(e(),l(c,null,{default:t(()=>[d(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SHORT%5B%22%E7%9F%AD%20RTT%22%5D%20--%3E%20FAST%5B%22%E6%AF%8F%E7%A7%92%E6%9B%B4%E5%A4%9A%E5%8A%A0%E4%B8%80%22%5D%0A%20%20LONG%5B%22%E9%95%BF%20RTT%22%5D%20--%3E%20SLOW%5B%22%E7%AA%97%E5%8F%A3%E6%B6%A8%E5%BE%97%E6%85%A2%22%5D%0A%20%20FAST%20--%3E%20SHARE%5B%22%E5%8D%A0%E6%9B%B4%E5%A4%9A%E7%93%B6%E9%A2%88%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=T('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Clos 内 RTT 同质，RTT 不公平不明显，incast 主导。公网 IXP 出口混流则明显。MSS 钳制让长 RTT 流每加一步字节更少，雪上加霜。多路径 MPTCP 后课可把子流 RTT 再搅一次。</p><p>应用层：把仓搬近（CDN）减 RTT，既降延迟也改善 TCP 份额——经济与控制耦合。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 FAST TCP 的全部。AQM：RED 与 CoDel 是下一课。后课默认：AIMD 偏袒短 RTT；要公平需调度或改控制律。</p><p>指责用户「窗口太大」之前先看 RTT 差。</p><p>上一课留下的缺口在本课收口；「RTT 不公平」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/aqm-red-codel">AQM：RED 与 CoDel</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>每 RTT 加一 ⇒ 短 RTT 更狠。</li><li>CUBIC/BBR 缓解不取消。</li><li>数据中心同质 RTT，公网否。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：Floyd–Jacobson；Chiu–Jain 对照。</li></ul>',10))])}const B=s(p,[["render",R]]);export{u as __pageData,B as default};
